
import { Router } from '@angular/router';
import { LoadingTestsManager } from '@src/loadingtests/LoadingTestsManager';

import { Player } from '@src/loadingtests/Player';

import { Directive, Component } from '@angular/core';
import { CommandTest } from '@src/loadingtests/CommandTest';

import { PlayerListComponent,config } from '@src/test_load_inner/PlayerListComponent';


import { Subject, ReplaySubject, firstValueFrom } from 'rxjs';

/* generated by template umlp.gui2ts.TSAnnotationDirective*/
@Component({
  standalone:true,
  imports:[...config.imports],
  selector: config.selector,
  templateUrl: config.templateUrl,
})
export class PlayerList extends PlayerListComponent {
  public override openPlayerInfo(player: Player): () => void {
    return () => {
      if (player != undefined && this.player != undefined) {
        if(this.selectedPlayer == player && this.displayed) {
          this.setDisplayed(false);
        }else {
          this.setSelectedPlayer(player);
          this.setDisplayed(true);
        }
      }
    };
  }


}

